function read(req){return new Promise((resolve,reject)=>{const chunks=[];let size=0,settled=false;const fail=error=>{if(settled)return;settled=true;reject(error);};if((req.headers['content-type']||'').split(';')[0].trim().toLowerCase()!=='application/json')return fail(Object.assign(new Error('Send request data as application/json.'),{status:415}));req.on('data',chunk=>{size+=chunk.length;if(size>256*1024){fail(Object.assign(new Error('Request body is too large.'),{status:413}));chunks.length=0;return;}if(!settled)chunks.push(chunk);});req.on('end',()=>{if(settled)return;try{const raw=Buffer.concat(chunks).toString('utf8'),body=raw?JSON.parse(raw):{};if(!body||typeof body!=='object'||Array.isArray(body))throw new Error();resolve(assertBodyIdentity(req,body));}catch(error){if(error.status)fail(error);else fail(Object.assign(new Error('Invalid JSON body.'),{status:400}));}});req.on('error',error=>fail(Object.assign(error,{status:400})));});}
function validateSlot(startAt,endAt){
 const validLocal=value=>{if(typeof value!=='string'||!/^\d{4}-\d\d-\d\dT\d\d:\d\d$/.test(value))return false;const d=new Date(value);return Number.isFinite(d.getTime())&&d.getFullYear()===Number(value.slice(0,4))&&d.getMonth()+1===Number(value.slice(5,7))&&d.getDate()===Number(value.slice(8,10))&&d.getHours()===Number(value.slice(11,13))&&d.getMinutes()===Number(value.slice(14,16));};
 if(!validLocal(startAt)||!validLocal(endAt)||new Date(endAt)<=new Date(startAt))throw Object.assign(new Error('Choose a valid start and end time.'),{status:400});
 if(new Date(startAt)<new Date(Date.now()-60000))throw Object.assign(new Error('Choose a future time slot.'),{status:400});
 if((new Date(endAt)-new Date(startAt))/3600000>8)throw Object.assign(new Error('Bookings are limited to 8 hours per slot.'),{status:400});
}
