function notifyEquipmentStaff(equipmentId,event,title,message){for(const user of db.prepare("SELECT id FROM users WHERE role IN ('technician','faculty','hod','admin')").all())db.prepare('INSERT INTO notifications(user_id,event_type,title,message,entity_type,entity_id) VALUES(?,?,?,?,\'equipment\',?)').run(user.id,event,title,message,equipmentId);}
function notify(userId,event,title,message,id){db.prepare('INSERT INTO notifications(user_id,event_type,title,message,entity_type,entity_id) VALUES(?,?,?,?,\'waitlist\',?)').run(userId,event,title,message,id);}
function detectUnusedReservations(){const policy=getPolicy(),cutoff=new Date(Date.now()-policy.no_show_grace_hours*3600000).toISOString(),rows=db.prepare("SELECT b.id,b.user_id,b.equipment_id,b.start_at,b.end_at,e.name equipment FROM bookings b JOIN equipment e ON e.id=b.equipment_id WHERE b.status='approved' AND b.end_at<=? AND NOT EXISTS(SELECT 1 FROM usage_events u WHERE u.booking_id=b.id AND u.source='verified') AND NOT EXISTS(SELECT 1 FROM booking_usage_reviews r WHERE r.booking_id=b.id)").all(cutoff);for(const b of rows){db.prepare("INSERT INTO booking_usage_reviews(booking_id,status) VALUES(?,'candidate')").run(b.id);db.prepare("INSERT INTO notifications(user_id,event_type,title,message,entity_type,entity_id) VALUES(?,'booking_usage_check','Check your equipment booking','We could not match a verified check-in to your '+b.equipment+' reservation. This is unverified and has no effect on future allocations. Contact lab staff if you checked in.','booking',?)").run(b.user_id,b.id);}}
function durationAdvice(userId,projectId,equipmentId,startAt,endAt,purpose='') {const project=db.prepare('SELECT * FROM projects WHERE id=? AND user_id=?').get(projectId,userId),equipment=db.prepare('SELECT * FROM equipment WHERE id=?').get(equipmentId);if(!project||!equipment)throw Object.assign(new Error('Choose your project and a valid equipment item.'),{status:400});const text=(project.description+' '+purpose+' '+project.requirements+' '+equipment.technical_profile+' '+equipment.category).toLowerCase();let hours=2;const reasons=[];if(/train|model|fabricat|print|machine|thermal study|long.?run|overnight/.test(text)){hours=4;reasons.push('The described build, fabrication or extended run suggests a longer session.');}else if(/calibrat|characteri[sz]|debug|integrat|prototype|measure|test|experiment/.test(text)){hours=3;reasons.push('The described testing, calibration or integration work suggests a multi-hour session.');}else reasons.push('A focused setup or validation session usually fits in a short block.');const maximum=Math.min(getPolicy().usage_limit,equipment.max_hours||8),recommended=Math.min(hours,maximum);if(recommended<hours)reasons.push(`Equipment and institutional limits cap this at ${maximum} hours.`);const booked=db.prepare("SELECT count(*) n FROM bookings WHERE equipment_id=? AND status='approved' AND start_at < ? AND end_at > ?").get(equipmentId,endAt,startAt).n,free=Math.max(0,equipment.total_units-booked);if(free===0)reasons.push('No units are currently free in this slot; the recommendation does not guarantee availability.');else reasons.push(`${free} of ${equipment.total_units} units are currently free in this slot.`);const slotHours=(new Date(endAt)-new Date(startAt))/3600000;if(slotHours>recommended)reasons.push(`Your requested reservation is ${slotHours} hours; consider reducing it to ${recommended} hours. A reviewer must approve any requested duration change.`);return {recommendedHours:recommended,maximumHours:maximum,availableUnits:free,taskBasis:reasons};}
function promoteWaitlist(equipmentId,freeStart,freeEnd){
 const equipment=db.prepare('SELECT * FROM equipment WHERE id=?').get(equipmentId);if(!equipment||equipment.operational_status!=='operational')return null;
 const expired=db.prepare("SELECT id,user_id FROM equipment_waitlist WHERE equipment_id=? AND status='offered' AND offer_expires_at<=?").all(equipmentId,new Date().toISOString());
 for(const row of expired){db.prepare("UPDATE equipment_waitlist SET status='expired',offered_start=NULL,offered_end=NULL,updated_at=CURRENT_TIMESTAMP WHERE id=?").run(row.id);notify(row.user_id,'waitlist_expired','Waitlist offer expired','The offered equipment slot expired before it was accepted.',row.id);}
 const pending=db.prepare("SELECT b.*,p.deadline FROM bookings b JOIN projects p ON p.id=b.project_id WHERE b.equipment_id=? AND b.status='pending' AND b.start_at < ? AND b.end_at > ? ORDER BY b.id").all(equipmentId,freeEnd,freeStart).map(b=>{try{return {...b,...evaluateRequest({userId:b.user_id,projectId:b.project_id,equipmentId,startAt:b.start_at,endAt:b.end_at,ignoreBookingId:b.id,allowCapacityConflict:true})};}catch{return {...b,eligible:false,score:0};}}).filter(x=>x.eligible).sort((a,b)=>b.score-a.score||a.id-b.id);
 const candidates=db.prepare("SELECT w.*,p.deadline FROM equipment_waitlist w JOIN projects p ON p.id=w.project_id WHERE w.equipment_id=? AND w.status='waiting' AND w.preferred_start>=? AND w.preferred_end<=? ORDER BY w.id").all(equipmentId,freeStart,freeEnd);
 const ranked=candidates.map(w=>{try{return {...w,...evaluateRequest({userId:w.user_id,projectId:w.project_id,equipmentId,startAt:w.preferred_start,endAt:w.preferred_end,allowCapacityConflict:true})};}catch{return {...w,eligible:false,score:0,blocks:['Project or equipment is no longer eligible.']};}}).filter(w=>w.eligible).sort((a,b)=>b.score-a.score||a.created_at.localeCompare(b.created_at)||a.id-b.id);
 for(const w of ranked){if(pending[0]&&pending[0].score>=w.score)continue;db.exec('BEGIN IMMEDIATE');try{
   const current=db.prepare("SELECT * FROM equipment_waitlist WHERE id=? AND status='waiting'").get(w.id);if(!current){db.exec('COMMIT');continue;}
   const busy=db.prepare("SELECT count(*) n FROM bookings WHERE equipment_id=? AND status='approved' AND start_at < ? AND end_at > ?").get(equipmentId,w.preferred_end,w.preferred_start).n;
   const held=db.prepare("SELECT count(*) n FROM equipment_waitlist WHERE equipment_id=? AND status IN ('offered','accepted_pending_approval') AND offered_start < ? AND offered_end > ?").get(equipmentId,w.preferred_end,w.preferred_start).n;
   if(busy+held>=equipment.total_units){db.exec('COMMIT');continue;}
   const expires=new Date(Date.now()+30*60*1000).toISOString();
   const decisionNote=`${w.note} Waitlist was compared with ${pending.length} eligible competing booking request(s); ${pending.length?'its fairness score ranked above them':'no eligible booking request outranked it'}.`;
   const upd=db.prepare("UPDATE equipment_waitlist SET status='offered',offered_start=preferred_start,offered_end=preferred_end,offer_expires_at=?,priority_score=?,fairness_note=?,updated_at=CURRENT_TIMESTAMP WHERE id=? AND status='waiting'").run(expires,w.score,decisionNote,w.id);
   if(upd.changes){notify(w.user_id,'waitlist_offer','Equipment slot offered',`${equipment.name} is available for your preferred slot. Accept within 30 minutes; faculty approval is still required.`,w.id);audit(null,'waitlist_slot_offered','waitlist',w.id,{equipmentId,score:w.score,slot:[w.preferred_start,w.preferred_end]});db.exec('COMMIT');return w.id;}
   db.exec('COMMIT');
  }catch(e){db.exec('ROLLBACK');if(String(e.message).includes('UNIQUE'))continue;throw e;}}
 return null;
}
function refreshExpiredOffers(){const expired=db.prepare("SELECT id,user_id,equipment_id,offered_start,offered_end FROM equipment_waitlist WHERE status='offered' AND offer_expires_at<=?").all(new Date().toISOString());for(const row of expired){const changed=db.prepare("UPDATE equipment_waitlist SET status='expired',offered_start=NULL,offered_end=NULL,updated_at=CURRENT_TIMESTAMP WHERE id=? AND status='offered'").run(row.id);if(changed.changes){notify(row.user_id,'waitlist_expired','Waitlist offer expired','The offered equipment slot expired before it was accepted.',row.id);audit(null,'waitlist_offer_expired','waitlist',row.id);promoteWaitlist(row.equipment_id,row.offered_start,row.offered_end);}}}
